"""按名字存取值的设置/获取节点对，获取节点带总开关。

官方的 Set/Get（KJNodes 那套）是纯前端虚拟节点：排队时被编译成真实连线，
后端不存在、也没有注册表，因此做不出运行时开关。这里改成后端真实节点：
设置节点执行时把值登记到名字注册表，获取节点按名字取回。
获取节点额外提供 `启用` 总开关和一个可选的 `直连值` 口（接了它就完全不查注册表，
连线本身也保证了执行顺序）。
"""

from __future__ import annotations

from typing import Any

_SET_REGISTRY: dict[str, Any] = {}


def _registry() -> dict[str, Any]:
    return _SET_REGISTRY


class QQSetNode:
    """把一个值登记到名字上，同时原样透传，方便串在链路中间。"""

    CATEGORY = "QQ/工具"
    FUNCTION = "set_value"
    RETURN_TYPES = ("*",)
    RETURN_NAMES = ("值",)
    DESCRIPTION = (
        "把输入的值登记到「名称」上，供 QQ-获取节点(可开关) 按名字取回；"
        "同时原样输出这个值，可以串在链路中间当透明节点用。"
    )

    @classmethod
    def INPUT_TYPES(cls):
        return {
            "required": {
                "名称": ("STRING", {"default": "value", "multiline": False}),
                "值": ("*",),
            },
        }

    @staticmethod
    def set_value(名称: str = "", 值: Any = None):
        name = str(名称 or "").strip()
        if not name:
            raise ValueError("QQ-设置节点 的名称不能为空")
        _SET_REGISTRY[name] = 值
        return (值,)


class QQGetNode:
    """按名字取回设置节点登记的值；启用关闭时输出 None。"""

    CATEGORY = "QQ/工具"
    FUNCTION = "get_value"
    RETURN_TYPES = ("*",)
    RETURN_NAMES = ("值",)
    DESCRIPTION = (
        "按「名称」取回 QQ-设置节点 登记的值。首行「启用」是总开关："
        "关闭时不查注册表、直接输出 None（下游把它当没接处理），等价于越过本节点。"
        "可选的 直连值 口接了就直接透传，不查注册表，连线也保证执行顺序。"
        "名称找不到对应设置节点时会报明确错误，不会静默输出空值。"
    )

    @classmethod
    def INPUT_TYPES(cls):
        return {
            "required": {
                "启用": ("BOOLEAN", {"default": True, "tooltip": "总开关。关闭时输出 None，不查注册表。"}),
                "名称": ("STRING", {"default": "value", "multiline": False}),
            },
            "optional": {
                "直连值": ("*", {"tooltip": "接了就直接透传这个值，不查注册表。"}),
            },
        }

    @staticmethod
    def get_value(启用: bool = True, 名称: str = "", 直连值: Any = None, **_kwargs: Any):
        if not 启用:
            return (None,)
        if 直连值 is not None:
            return (直连值,)
        name = str(名称 or "").strip()
        if name not in _SET_REGISTRY:
            known = "、".join(sorted(_SET_REGISTRY)) or "（目前没有任何已登记的名称）"
            raise ValueError(f"QQ-获取节点 找不到名称「{name}」；已登记的名称：{known}")
        return (_SET_REGISTRY[name],)


NODE_CLASS_MAPPINGS = {
    "QQSetNode": QQSetNode,
    "QQGetNode": QQGetNode,
}
NODE_DISPLAY_NAME_MAPPINGS = {
    "QQSetNode": "QQ-设置节点",
    "QQGetNode": "QQ-获取节点(可开关)",
}
